WITH payload AS (SELECT $archive_payload$[{"id":"2175f720-7c85-50bf-93b3-4ec4dd6fd3da","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -إنكار الدعوى -رجوع عن اعتراف -محضر استشمام -عدم احلد بالرائحة -قبول الرجوع عن اإلقرار يف احلدود -احلدود تدرأ بالشبهات -التعزير باجللد .","document_number":"34204097","case_number":"34332","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/2","year":"1434","subject":"مسكر -شرب مسكر -إنكار الدعوى -رجوع عن اعتراف -محضر استشمام -عدم احلد بالرائحة -قبول الرجوع عن اإلقرار يف احلدود -احلدود تدرأ بالشبهات -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 34204097‬تاريخه‪1434/5/2:‬هـ‬\n                            ‫رقم الدعوى‪34332:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34308116‬تاريخه‪1434/8/29 :‬هـ‬\n\n\n     ‫مســكر ‪ -‬شــرب مســكر ‪ -‬إنــكار الدعــوى ‪ -‬رجــوع عــن اعتــراف ‪ -‬محضــر‬\n     ‫استشــمام ‪ -‬عــدم احلــد بالرائحــة ‪ -‬قبــول الرجــوع عــن اإلقــرار يف‬\n                   ‫احلــدود ‪ -‬احلــدود تــدرأ بالشــبهات ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n     ‫مــا قــرره أهــل العلــم بقبــول رجــوع املقــر عــن إقــراره‪ ،‬يف احلــدود قــال ابــن‬\n       ‫قدامــة يف الــكايف ‪ ( 309/4‬وإن أقــر بحــد ثــم رجــع عنــه قبــل رجوعــه) ‪.‬‬\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املسـ ــكر ‪ ،‬وطلب إثبات‬\n     ‫ما أسند إليه واحلكم عليه بحد املســكر ‪ ،‬وحيث ورد بالغ عن وجود‬\n     ‫املدعــى عليــه ملقــى علــى األرض ومصــاب فتــم إبــاغ الهــال األحمــر ومت‬\n     ‫إســعافه والذي اتضح أنه بحالة ســكر ‪ ،‬وباسـتـشـ ــمامه اتضح انبعاث‬\n     ‫رائحــة املســكر مــن أنفاســه ‪ ،‬وأنكــر املدعــى عليــه الدعــوى وكانــت‬\n     ‫بينة املدعي ال ـعـ ــام اع ـتـ ــراف املدعـ ــى عليه تـ ـح ـق ـي ـ ـقـ ـ ًا ‪،‬ودف ــع املدعى‬\n     ‫عليــه بأنــه اعتــرف حتقيقـ ًا للخــروج مــن التوقيــف ‪ ،‬ولعــدم ثبــوت إدانــة‬\n     ‫املدعــى عليــه بشــرب املســكر ودرء احلــد عنــه لرجوعــه عــن إقــراره فقــد‬\n     ‫حكمــت احملكمــة بتعزيــره لتهمــة شــرب املســكر بجلــده ســبعني‬\n     ‫جلــدة دفعــة واحــدة علن ـ ًا ‪،‬وقنــع املدعــى عليــه واعتــرض املدعــي العــام‬\n                     ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬           ‫بــدون الئحــة ُ‬\n‫‪19‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 34332‬وتاريــخ ‪ 1434/01/03‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341541‬وتاريــخ ‪ 1434/01/03‬ه ـ ففــي يــوم‬\n‫األحد املوافق‪ 1434/04/21‬هـ افتتحت اجللســة الســاعة ‪ 10 : 45‬وفيها‬\n‫حضــر املدعــي العــام ‪.....‬وحضــر حلضــوره ‪.....‬ســعودي اجلنســية ســجله ‪.....‬‬\n‫وادعــى املدعــى العــام قائــا حيــث انه بتاريــخ ‪1433/11/26‬هـ ورد بالغ‬\n‫مــن العمليــات عــن شــخص ملقــى علــى األرض بحــي ‪.....‬بالدمــام ومصاب‬\n‫فتــم إبــاغ الهــال األحمــر ومت تقــدمي اإلســعافات األوليــة للشــخص الــذي‬\n‫اتضــح انــه املدعــى عليــه وتبــن انــه بحالــة ســكر وباستشــمامه اتضــح‬\n‫انبعــاث رائحــة املســكر مــن أنفاســه وتعــذر ســماع أقوالــه كونــه بحالــة‬\n‫ســكر وباســتجوابه‪ /‬اقــر بشــربه املســكر وال يعلــم عــن ســبب إصابتــه‬\n‫واليتهــم أحــدا يكــون ســببا يف إصابتــه وانتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام ل‪.....‬بشــرب املســكر ‪ ،‬وذلــك لألدلــة والقرائــن اآلتيــة ‪/1:‬‬\n‫اعترافــه املــدون علــى الصفحــة رقــم (‪ )12‬مــن تقريــر األحــوال األمنيــة‬\n‫املوحــد لفــة رقــم (‪ /2)1‬مــا جــاء يف البــاغ املــدون على الصفحــة رقم (‪)1‬‬\n‫مــن تقريــر األحــوال األمنيــة املوحــد لفــة رقــم (‪ /3)1‬محضــر االستشــمام‬\n‫املــدون علــى الصفحــة رقــم (‪)6‬مــن تقريــر األحــوال األمنيــة املوحــد لفــة‬\n‫رقــم (‪ /4 )1‬محضــر تعــذر ســماع أقوالــه املــدون علــى الصفحــة رقــم‬\n‫(‪)6‬مــن تقريــر األحــوال األمنيــة املوحــد لفــة رقــم (‪ )1‬وبالبحــث عمــا‬\n‫إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة وحيــث‬\n\n                                                                                   ‫‪20‬‬\n\f     ‫إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n     ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n     ‫واحلكــم عليــه بحــد املســكر هــذه دعــواي وبســؤال املدعــى عليــه أجــاب‬\n     ‫قائــا مــا ذكــر املدعــى العــام يف دعــواه غيــر صحيــح حيــث أنــي لــم‬\n     ‫أشــرب املســكر و قــد اعترفــت بشــرب املســكر لــدى الشــرطة وكان‬\n     ‫اعتــرايف هــذا خالفــا للحقيقــة و الواقــع و ســبب اعتــرايف لــدى الشــرطة‬\n     ‫أنــي كنــت موقوفــا لديهــم فاعترفــت لكــي اخــرج مــن التوقيــف‬\n     ‫بكفالــة رغــم أنــي لــم اشــرب اخلمــر املســكر هكــذا أجــاب وبعــد‬\n     ‫ســماع الدعــوى واإلجابــة جــرى االطــاع علــى اعترافــه املــدون علــى‬\n     ‫صفحــة ( ‪ ) 11-10-9‬مــن ملــف التحقيــق ومحضــر االستشــمام املــدون‬\n     ‫علــى الصفحــة رقــم ( ‪ ) 6‬مــن ملــف التحقيــق املرفــق حيــث وجــد مطابقــا‬\n     ‫ملــا ذكــر يف الئحــة االدعــاء العــام هــذا وبطلبــي مــن املدعــي العــام زيــادة‬\n     ‫بينــة قــال ليــس لــدي ســوى مــا يف أوراق املعاملــة هكــذا قــرر فبنــاء علــى‬\n     ‫مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه أنكــر دعــوى‬\n     ‫املدعــي العــام وحيــث ليــس للمدعــي العــام بينــة ســوى محضــر استشــمام‬\n     ‫املدعــى عليــه واعترافــه حتقيــق الــذي رجــع عنــه وحيــث أن حد املســكر‬\n     ‫ال يقــام بالرائحــة وحيــث أن رجوعــه عــن إقــراره فيمــا يوجــب احلــد يقبــل‬\n     ‫منــه و لــو كان هــذا اإلقــرار باملجلــس الشــرعي قــال ابــن قدامــة رحمــه‬\n     ‫اهلل تعالــى يف كتــاب الــكايف (ج‪ ، )309 / 4‬وإن أقــر بحــد ثــم رجــع‬\n     ‫عنــه قبــل رجوعــه ‪ ،‬لــذا فإنــه لــم يثبــت لــدى شــرعا إدانتــه بشــرب اخلمــر‬\n     ‫املســكر وتتوجــه عليــه التهمــه يف ذلــك للقرائــن التــي ذكرهــا املدعــي‬\n     ‫العــام يف دعــواه و حكمــت باآلتــي ‪ /1 :‬درء حــد املســكر عــن املدعــى‬\n     ‫عليــه لرجوعــه عــن إقــراره ‪/2‬تعزيــر املدعــى عليــه علــى التهمــه يف‬\n\n\n‫‪21‬‬\n\f‫شــربه للخمــر املســكر بجلــده ســبعني جلــده دفعــة واحــدة علنــا وبعــرض‬\n‫احلكــم علــى املدعــى عليــه قــرر قناعتــه بــه كمــا قــرر املدعــي العــام‬\n‫املعارضــة وطلــب اســتئناف احلكــم مكتفيــا بالئحــة الدعــوى وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                            ‫حرريف‪1434/4/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/2047100‬ج‪ 2‬وتاريــخ ‪1434/8/24‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n‫‪ 341188002‬وتاريــخ ‪1434/8/17‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ ‪..... /‬املســجل برقــم ‪34204097‬‬\n‫وتاريــخ ‪1434/5/2‬ه ـ اخلــاص بدعوى‪/‬املدعــي العام ضــد‪ ...../‬يف قضية‬\n‫خمــور وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n                                                       ‫حــرر يف ‪1434/8/29‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪22‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":19,"source_page_end":22,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e429a0fed0ca90a297f5765622eeb8e67ff2b49bde1a9af896837d1913855756","normalized_text_hash":"99c68a47150a9a401ce3c96a8d676bd8b5b0ce63a17dad0a241e0610d80c6120","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p19-34204097"},{"id":"45810f19-53f7-5b39-a905-c67745358cda","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -مقاومة املدعى عليه رجال األمن -اعتداء بالضرب -التستر على الهارب -حد املسكر -تعزير بالسجن واجللد للشبهة .","document_number":"346428","case_number":"344201","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/7","year":"1434","subject":"مسكر -شرب مسكر -مقاومة املدعى عليه رجال األمن -اعتداء بالضرب -التستر على الهارب -حد املسكر -تعزير بالسجن واجللد للشبهة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 346428 :‬تاريخه ‪1434/1/7 :‬هـ‬\n                         ‫رقم الدعوى ‪344201 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3430841‬تاريخه‪1434/02/05:‬هـ‬\n\n\n     ‫مســكر ‪ -‬شــرب مســكر ‪ -‬مقاومــة املدعــى عليــه رجــال األمــن ‪ -‬اعتــداء‬\n     ‫بالضــرب ‪ -‬التســتر علــى الهــارب ‪ -‬حــد املســكر ‪ -‬تعزيــر بالســجن‬\n                                                              ‫واجللــد للشــبهة ‪.‬‬\n\n\n\n\n     ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( مــن شــرب اخلمــر فاجلــدوه ) رواه‬\n                                               ‫أحمــد وأبــو داود والنســائي ‪.‬‬\n     ‫‪ -2‬إجمــاع الصحابــة علــى جلــد شــارب اخلمــر ثمانــن جلــدة وهــو‬\n          ‫املذهــب وعليــه جماهيــر األصحــاب (كشــاف القنــاع ‪) 99/14‬‬\n                                                     ‫و( االنصاف ‪. ) 441/15‬‬\n\n\n\n\n     ‫ادعـ ــى املدعــي العــام ضــد املدعــى عليــه بشــرب املـ ـسـ ـكـ ــر ومقاومــة‬\n     ‫رجــال األم ـ ــن واالعتــداء علــى مـ ــقيم بضربــه والتســتر علــى رفيقــه‬\n     ‫الهــارب ‪،‬وطلــب إثبــات مــا أســند إليــه واحل ـكـ ـ ــم عليــه بحد امل ـ ـسـ ـك ــر‬\n     ‫وعقوبــة تعزيريــة لالعتــداء ‪،‬حيــث ورد بــاغ عــن وجــود مضاربــة وعنــد‬\n     ‫وصــول الدوريــة األمنيــة وجــد املجنــي عليــه وأفــاد بأنــه تعــرض للضــرب‬\n     ‫ومحاولــة الســلب مــن قبــل املدعــى عليــه فتــم القبــض عليــه وقــام مبقاومــة‬\n     ‫رجــال األمــن ‪،‬وأقــر املدعــى عليــه بشــرب املســكر وأنكــر بقيــة التهــم‬\n‫‪23‬‬\n\f‫‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بإقامــة حــد املســكر ثمانــن‬\n‫جلــدة دفعــة واحــدة يف مــكان عــام وبتعزيــره للشــبهة بســجنه شــهر ًا‬\n‫وجلــده خمســن جلــدة دفعــة واحــدة ‪،‬وقنــع املدعــى عليــه ‪،‬واعتــرض‬\n‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬ ‫املدعــي العــام بــدون الئحــة ُ‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة مــن‬\n‫هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمة برقــم ‪3418278‬‬\n‫وتاريــخ ‪1434/1/4‬ه ـ واحملالــة لنــا مــن فضيلة رئيــس احملكمة اجلزائية‬\n‫بالدمــام برقــم ‪ 344201‬وتاريــخ ‪1434/1/4‬ه ـ افتتحــت اجللســة يف يــوم‬\n‫األربعاء ‪1434/1/7‬هـ الســاعة احلادية عشــرة والربع وفيها قدم املدعي‬\n‫ا فيهــا بصفتــي مدعيـ ًا عامـ ًا بدائــرة االدعــاء العــام‬    ‫العــام ‪.....‬دعــواه قائـ ً‬\n‫لفــرع املنطقــة الشــرقية أدعــي علــى‪..... /‬مجهــول الهوية مبوجــب البطاقة‬\n‫البديلــة رقــم ‪.....‬حيــث إنــه بتاريــخ ‪1433/12/9‬ه ـ وأثنــاء قيــام الدوريــات‬\n‫األمنيــة بعملهــا املعتــاد ورد بــاغ عــن وجــود مضاربــة يف حــي النخيــل‬\n‫وعنــد وصــول الدوريــات األمنيــة وجــد املدعــي ‪ .....‬وأفــاد بأنــه تعــرض‬\n‫للضــرب ومحاولــة الســلب مــن قبــل املدعــى عليــه فتــم القبــض عليــه وقــام‬\n‫مبقاومــة رجــال األمــن وبســماع أقــوال املدعــي ‪.....‬أفــاد بقيــام شــخصني‬\n‫مــن اجلنســية اليمنيــة بالدخــول عليــه يف مقــر ســكنه واالعتــداء عليــه‬\n‫بالضــرب وأخــذ محفظتــه وعندمــا وجودهــا فارغــة قامــوا بإعادتهــا فقام‬\n‫بإبــاغ الدوريــات األمنيــة ومت القبــض على املتهــم املذكور وهرب اآلخر‬\n‫(مت مخاطبــة الشــرطة ملواصلــة البحــث والتحــري عــن املتهــم الهــارب‬\n                                                                                              ‫‪24‬‬\n\f     ‫مبوجــب خطابنــا رقــم ‪.....‬وتاريــخ ‪1433/12/21‬هــ) وباســتجواب املتهــم‬\n     ‫أقــر بشــرب اخلمــر وأنكــر االعتــداء بالضــرب ومقاومــة رجــال األمــن‬\n     ‫والتســتر علــى رفيقــه الهــارب وباستشــمام املتهــم اتضــح انبعــاث رائحــة‬\n     ‫املســكر مــن أنفاســه صــدر للمجنــي عليــه التقريــر الطبــي مــن مجمــع‬\n     ‫الدمــام برقــم ‪.....‬وتاريــخ ‪1433/12/21‬ه ـ املتضمــن أنــه بالكشــف‬\n     ‫علــى املذكــور بتاريــخ ‪1433/12/9‬ه ـ وجــد مصابـ ًا بجــرح قطعــي علــى‬\n     ‫الشــفتني وعلــى الوجــه مــع كدمــه علــى الوجــه ونزيــف حتــت امللتحمــة‬\n     ‫للعــن اليســرى إثــر ادعــاء اعتــداء مت عمــل العــاج الــازم وأشــعة علــى‬\n     ‫األنــف وحتويلــه إلــى العيــون ومــدة الشــفاء ثمانيــة أيــام مــا لــم حتــدث‬\n     ‫مضاعفــات وقــد انتهــى التحقيــق إلــى اتهام‪.....‬بشــرب املســكر ومقاومــة‬\n     ‫رجــال األمــن واالعتــداء بالضــرب علــى املقيــم‪ .....‬والتســتر علــى رفيقــه‬\n     ‫الهــارب مــن الضبــط اجلنائــي وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬إقــرار‬\n     ‫املتهــم بشــرب املســكر واملــدون يف محضــر االســتجواب علــى اللفــة‬\n     ‫رقــم (‪ -2 )7/6‬محضــر الدوريــات األمنيــة املرفــق علــى اللفــة رقــم (‪)3‬‬\n     ‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق وحيــث إن مــا أقــدم عليــه‬\n     ‫املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب‬\n     ‫عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪-1 :‬‬\n     ‫حــد املســكر لقــاء شــربه لــه ‪ -2‬عقوبــة تعزيريــة تزجــره وتــردع غيــره‬\n     ‫لقــاء مــا قــام بــه مــن اعتــداء والتشــديد عليــه يف العقوبــة اســتناد ًا لتعميــم‬\n     ‫ســمو النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‬\n     ‫‪ ) 36717‬وتاريــخ ‪1431/6/11‬ه ـ هكــذا ادعــى وبعــرض الدعــوى علــى‬\n     ‫ا مــا ذكــره املدعــي العــام مــن قيامــي بشــرب‬    ‫املدعــى عليــه أجــاب قائـ ً‬\n     ‫املســكر فذلــك صحيــح وأمــا االعتــداء بالضــرب ومقاومــة رجــال األمــن‬\n\n\n‫‪25‬‬\n\f‫والتســتر علــى الشــخص اآلخــر فذلــك غيــر صحيــح هكــذا أجــاب ثــم‬\n‫جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال بينتــي مــا جــاء يف‬\n‫أوراق املعاملــة ثــم جــرى االطــاع علــى أوراق املعاملــة فوجــدت علــى لفــة‬\n‫رقــم (‪ )3‬محضــر تنفيــذ مهمــة املعــد مــن قبــل رجــل األمــن ‪ .....‬املتضمــن‬\n‫ـاء علــى مــا تقــدم مــن دعــوى‬\n                                ‫طبــق مــا ذكــر املدعــي العــام يف دعــواه فبنـ ً‬\n‫املدعــي العــام وإجابــة املدعــى عليــه وإقــراره بشــرب املســكر وهــو‬\n‫بكامــل أهليتــه املعتبــرة شــرع ًا ولقولــه صلــى اهلل عليــه وســلم (مــن‬\n‫شــرب اخلمــر فاجلــدوه) رواه أحمــد وأبــو داود والنســائي كمــا انعقــد‬\n‫إجمــاع الصحابــة رضــي اهلل عنهــم علــى جلــد شــارب اخلمــر ثمانــون جلــدة‬\n‫(كشــاف القنــاع عــن اإلقنــاع ‪ )99/14‬وهــو املذهــب وعليــه جماهيــر‬\n‫األصحــاب (اإلنصــاف ‪ )441/15‬ومبــا أن بينــة املدعــي العــام لــم تكتمل‬\n‫علــى مقاومــة املدعــى عليــه لرجــال األمــن واعتدائــه علــى أحــد املقيمــن‬\n‫وتســتره علــى الشــخص الهــارب لــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n‫عليــه ‪.....‬بشــرب اخلمــر املســكر ولــم يثبــت لــدي مقاومتــه لرجــال األمــن‬\n‫واالعتــداء بالضــرب علــى أحــد املقيمــن وتســتره علــى الشــخص الهــارب‬\n‫وقــررت اآلتــي‪ :‬أوالً‪ :‬جلــد املدعــى عليــه ثمانــن جلــدة دفعــة واحــدة حــد‬\n‫املســكر ويكــون التنفيــذ يف مــكان عــام يحضــره جمــع مــن النــاس‪.‬‬\n‫ثاني ـاً‪ :‬ســجن املدعــى عليــه ملــدة شــهر تبــدأ مــن تاريــخ إيقافــه وجلــده‬\n‫خمســن جلــدة تعزيــر ًا دفعــة واحــدة لقــاء شــبهة مقاومــة رجــال األمــن‬\n‫وشــبهة االعتــداء علــى أحــد املقيمــن وشــبهة التســتر علــى شــخص آخــر‬\n‫وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة باحلكــم كمــا قــرر املدعــي العــام االعتــراض علــى احلكــم‬\n‫وطلــب االســتئناف مكتفي ـ ًا بالئحــة الدعــوى العامــة وبــاهلل التوفيــق‬\n\n\n                                                                                      ‫‪26‬‬\n\f                   ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/1/7‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪/34/246958‬ج‪ 2‬وتاريــخ ‪1434/1/28‬ه ـ الواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪34/18278‬‬\n     ‫وتاريــخ ‪1434/1/24‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ‪ /‬املســجل برقــم ‪ 346428‬وتاريــخ ‪1434/1/7‬ه ـ‬\n     ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪( /‬مجهــول الهويــة) يف قضيــة‬\n     ‫مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n     ‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n     ‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                      ‫وســلم‪ .‬حــرر يف ‪1434/2/5‬ه ـ ‪.‬‬\n\n\n\n\n‫‪27‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":23,"source_page_end":27,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"51b35a97be3661087865ebb3c2117abf4045887fbfa10a3ce6d98a9935fceb6a","normalized_text_hash":"5779e1dc73aeb6233254e4ce0d431f802453b45a821f2da653c5a76ec33a4361","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p23-346428"},{"id":"7d05be8e-ef14-5816-a32b-2a343e748490","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قدوم مسافر يف حالة سكر -تعاطي احلشيش -إقامة حد املسكر -التعزير بالسجن واملنع من السفر .","document_number":"34188189","case_number":"3352875","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/15","year":"1434","subject":"مسكر -شرب املسكر -قدوم مسافر يف حالة سكر -تعاطي احلشيش -إقامة حد املسكر -التعزير بالسجن واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34188189 :‬تاريخه ‪1434/04/15 :‬هـ‬\n                     ‫رقم الدعوى ‪3352875 :‬‬\n              ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34204237:‬تاريخه‪1434/05/04 :‬هـ‬\n\n\n ‫مســكر ‪ -‬شــرب املســكر ‪ -‬قدوم مســافر يف حالة ســكر ‪ -‬تعاطي احلشــيش‬\n           ‫‪ -‬إقامة حد املســكر ‪ -‬التعزير بالســجن واملنع من الســفر ‪.‬‬\n\n\n\n\n                      ‫‪ -1‬قوله صلى اهلل عليه وسلم ‪ ( :‬كل مسكر حرام )‪.‬‬\n                                              ‫‪ -2‬قاعدة ‪ :‬املرء مؤاخذ بإقراره‬\n ‫‪ -3‬قــال ابــن حجــر يف فتــح البــاري (‪ ( : )45/10‬واســتدل مبطلــق قولــه‬\n ‫صلــى اهلل عليــه وســلم «كل مســكر حــرام» علــى حتــرمي مــا يســكر ولــو‬\n ‫لــم يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي‬\n                                                       ‫وغيــره بأنهــا مســكرة ) ‪.‬‬\n                  ‫‪ -4‬املواد (‪ )41‬و (‪ )56‬و (‪ )60‬من نظام مكافحة املخدرات‬\n                                               ‫‪ -5‬املادة (‪ )68‬من نظام املرور ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n ‫وشــرب املســكر وقيــادة الســيارة حتــت تأثيــر املســكر واحلشــيش‬\n ‫املخــدر وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n ‫بعقوبــة الســجن واملنــع مــن الســفر وفــق نظــام مكافحــة املخــدرات‬\n ‫واحلكــم عليــه بحــد املســكر ‪ ،‬حيــث قبــض علــى املدعــى عليــه أثنــاء‬\n\n                                                                                     ‫‪34‬‬\n\f     ‫قدومــه للمملكــة بســيارته قادم ـ ًا مــن إحــدى الــدول املجــاورة وقــام‬\n     ‫باالعتــراض علــى اإلجــراءات اجلمركيــة والتلفــظ علــى أحــد موظفــي‬\n     ‫اجلمــارك ‪،‬وباستشــمامه اتضــح بــأن رائحــة املســكر تفــوح مــن فمــه‪،‬‬\n     ‫أثبــت تقريــر الســموم الشــرعية إيجابيــة عينــة ســوائله ملــادة الكحــول‬\n     ‫ومركبــات احلشــيش ‪ ،‬كمــا أقــر املدعــى عليــه مبــا نســب إليــه‪ ،‬وبنــاء‬\n     ‫علــى مــا تقــدم حكمــت احملكمــة علــى املدعــى عليــه بإقامــة حــد‬\n     ‫املســكر بجلــده ثمانــن جلــدة و تعزيــره بالســجن واملنــع مــن الســفر‬\n     ‫وإثبــات قيادتــه للســيارة حتــت تأثيــر املســكر واحلشــيش وعقوبتــه يف‬\n     ‫ذلــك عائــدة للجهــة املختصــة وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي املنــدوب يف احملكمة اجلزائية‬\n     ‫بالدمــام بنــاء علــى قــرار رئيــس املجلــس األعلــى للقضــاء رقــم ‪ ......‬وتاريــخ‬\n     ‫‪....../....../......‬ه ـ وبنــاء علــى املعاملــة احملالــة لنــا مــن رئيــس احملكمــة‬\n     ‫برقــم ‪ ......‬يف ‪ ....../....../......‬ه ـ واملقيــدة برقــم ‪ ......‬يف ‪....../....../......‬ه ـ‬\n     ‫يف يوم األحد ‪....../...... /......‬هـ افتتحت اجللســة الســاعة العاشــرة وفيها‬\n     ‫حضــر املدعــى عليــه اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ...... ......‬وقــدم‬\n     ‫املدعــي العــام دعــواه ضــد املدعــى عليــه التــي جــاء فيهــا ادعــي علــى‬\n     ‫املدعــى عليــه اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ......‬مفــرج عنــه حيــث‬\n     ‫انــه باالطــاع علــى خطــاب مديــر مكافحــة املخــدرات بجســر امللــك‬\n     ‫فهــد رقــم (‪ )......‬وتاريــخ ‪....../....../......‬ه ـ وكــذا محضــر تنفيــذ املهمــة‬\n     ‫املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات األمنيــة وكامــل أوراق‬\n     ‫القضيــة تبــن أنــه قبــض علــى املدعى عليه بتاريخ ‪ ...... /....../......‬هـ وهو‬\n\n‫‪35‬‬\n\f‫قــادم مــن ‪ ................‬ويقــود ســيارة مــن نــوع (‪ ).....‬اثــر قيامــه باالعتــراض‬\n‫علــى اإلجــراءات اجلمركيــة والتلفــظ علــى احــد موظفــي جمــرك جســر‬\n‫امللــك فهد(انتهــت قضيــة التلفــظ بالتنــازل) وباستشــمامه اتضــح بــان‬\n‫رائحــة املســكر تفــوح مــن أنفاســه وتعــذر ســماع أقوالــه يف حينــه كونــه‬\n‫بحالــة ســكر وببعثــه للمركــز اإلقليمــي ملراقبــة الســموم صــدر بحقــه‬\n‫تقريــر الســموم الشــرعي رقــم(‪ )..............‬وتاريــخ ‪ ....../....../......‬املخــدر‬\n‫واحملظــور دوليـ ًا وقــد أفــرج عنــه بالكفالــة احلضوريــة بتاريــخ‪..../..../....‬‬\n‫ه ـ ومت بعثــه إلــى شــعبة مكافحــة املخــدرات بالدمــام بتاريخ‪../..../....‬ه ـ‬\n                                                                    ‫اثــر تلــك القضيــة‪.‬‬\n‫وبســماع أقوالــه مــن قبــل رجــال الضبــط بشــعبة مكافحــة املخــدرات‬\n‫بالدمــام وكــذا مبركــز شــرطة اجلســر أقــر بصحــة واقعــة القبــض‬\n‫عليــه وشــرب املســكر وقيــادة الســيارة بحالــة ســكر نافي ـ ًا تعاطيــه‬\n                                                                          ‫للمخــدرات‪.‬‬\n                                    ‫وانتهى التحقيق معه إلى اتهامه مبا يلي‪-:‬‬\n                             ‫‪-1‬تعاطي مادة احلشيش املخدر وشرب املسكر‪.‬‬\n                   ‫‪-2‬قيادة السيارة حتت تأثير املسكر واحلشيش املخدر‪.‬‬\n                                                      ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬مــا ورد بأقوالــه األوليــة املنــوه عنهــا املدونــة علــى الصفحتــن رقــم(‪-0‬‬\n‫‪ )0‬مــن ملــف ضبــط إجــراءات قضيــة املرفــق وعلــى الصفحــة رقــم(‪ )0‬مــن‬\n                                                        ‫ملــف تقريــر األحــوال األمنية‪.‬‬\n‫‪ -2‬مــا ورد بخطــاب مديــر مكافحــة املخــدرات بجســر امللــك فهــد‬\n                                                      ‫املرفــق علــى اللفــة رقــم(‪)00‬‬\n                            ‫‪ -3‬محضر تنفيذ املهمة املرفق على اللفة رقم(‪)0‬‬\n\n\n                                                                                            ‫‪36‬‬\n\f     ‫‪ -4‬محضــر تعــذر االســتجواب املــدون علــى الصفحــة رقــم(‪ )0‬مــن ملــف‬\n                                                                 ‫تقريــر األحــوال األمنيــة‬\n     ‫‪ -5‬محضــر االستشــمام املــدون علــى الصفحــة رقــم(‪ )0‬مــن ملــف تقريــر‬\n                                                                         ‫األحــوال األمنيــة‪.‬‬\n             ‫‪ -6‬تقرير السموم الشرعي املنوه عنه املرفق على اللفة رقم(‪)00‬‬\n     ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n                     ‫شــرع ًا فعــل محــرم شــرعا ومجــرم نظام ـ ًا اطلــب مــا يلــي‪-:‬‬\n     ‫أوال‪ :‬إثبــات مــا اســند إليــه مــن تعاطــي مــادة احلشــيش املخدر وفــق الفقرة‬\n     ‫رقــم(‪ )2‬مــن املــادة رقــم(‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                    ‫العقليــة واحلكــم عليــه مبــا يلــي‪-:‬‬\n     ‫‪-1‬عقوبــة الســجن الــواردة بالفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪ )41‬مــن‬\n                                                                                    ‫النظــام‪.‬‬\n            ‫‪-2‬منعه من السفر وفق الفقرة (‪ )1‬من املادة رقم(‪ )56‬من النظام‪.‬‬\n     ‫ثانيـاً‪ -:‬إثبــات شــربه للمســكر واحلكــم عليــه بحــد الســكر لقــاء ذلــك‬\n                                                           ‫ولتعاطيــه للحشــيش املخدر‬\n     ‫ثالث ـاً‪ -:‬إثبــات قيادتــه للمركبــة حتــت تأثيــر املســكر واحلشــيش‬\n     ‫املخــدر وفــق الفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور‬\n     ‫وإفهامــه بــأن عقوبتــه الــواردة بالفقــرة رقــم(‪ )1‬مــن املــادة رقــم(‪)68‬‬\n     ‫مــن نظــام املــرور تقــرر مــن اجلهــة املختصــة وفــق الفقــرة(‪ )2‬مــن قــرار‬\n     ‫مجلــس الــوزراء رقــم ‪ 315‬وتاريــخ ‪1428/10/24‬ه ـ وبســؤال املدعــى‬\n     ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام صحيــح جملــة وتفصيــا‬\n     ‫فقــد شــربت املســكر وتعاطيــت احلشــيش املخــدر وقــدت الســيارة حتــت‬\n     ‫تأثيــر املســكر واحلشــيش املخــدر وأنــا تائــب ونــادم هــذه إجابتــي وبعــد‬\n\n\n‫‪37‬‬\n\f‫تدويــن مــا ســبق جــرى االطــاع علــى التقريــر الكيمــاوي الشــرعي رقــم‬\n‫‪ ......‬املتضمــن إيجابيــة العينــة املرســلة يف هــذه القضيــة ملــادة احلشــيش‬\n‫املخــدر كمــا جــرى االطــاع علــى صحيفــة ســوابق املدعــى عليــه وقــد‬\n‫تضمنــت عــدم وجــود ســوابق علــى املدعــى عليــه فبنــاء علــى مــا تقــدم مــن‬\n                                                               ‫الدعــوى واإلجابــة‬\n‫املتضمنــة املصادقــة عليهــا وحيــث أن املــرء مؤاخــذ بإقــراره وبنــاء علــى‬\n‫مــا نــص عليــه أهــل العلــم مــن إقامــة حــد املســكر علــى متنــاول احلشــيش‬\n‫قــال ابــن حجــر يف فتــح الباري(‪»)45/10‬و ُأســتدل مبطلــق قوله صلى اهلل‬\n‫عليــه وســلم «كل مســكر حــرام» علــى حتــرمي مــا يســكر ولــو لــم يكن‬\n‫شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد جزم النــووي وغيره بأنها‬\n‫مســكرة «وبنــاء علــى التقريــر الكيمــاوي الشــرعي املشــار إليــه أعــاه‬\n‫واســتناد ًا للمــادة احلاديــة واألربعــن واملــادة السادســة واخلمســن واملــادة‬\n‫الســتني مــن نظــام املخــدرات واملؤثــرات العقليــة ولعــدم احليــازة واســتناد ًا‬\n‫للمــادة الثامنــة والســتني مــن نظــام املــرور لــذا فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه مبــا يلــي‪ :‬أوالً‪ /‬شــرب املســكر وتعاطــي احلشــيش املخــدر‬\n‫وحكمــت عليــه لقــاء ذلــك بجلــده حــد املســكر ثمانــن جلــدة وســجنه‬\n‫ثالثــة أشــهر ومنعــه مــن الســفر خــارج اململكــة مــدة ســنتني تبــدأ بعــد‬\n‫االنتهــاء مــن تنفيــذ عقوبــة الســجن احملكــوم بهــا ثانيـاً‪ /‬قيــادة الســيارة‬\n‫حتــت تأثيــر املســكر و احلشــيش املخــدر وأفهمتــه بــأن عقوبتــه علــى‬\n‫ذلــك عائــدة للجهــة املختصــة وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n‫عــدم القناعــة وطلــب رفــع احلكــم إلــى محكمــة االســتئناف بالئحــة‬\n‫فأجيــب لطلبــه وأفهــم باملراجعــة يــوم األربعــاء املوافــق ‪0000/0/00‬ه ـ‬\n‫الســتالم نســخه مــن احلكــم وتقــدمي اعتراضــه عليــه خــال مهلــة ثالثــن‬\n\n\n                                                                                       ‫‪38‬‬\n\f     ‫يومــا وأنــه إذا انتهــت هــذه املهلــة ســقط حقــه يف االعتــراض وســيتم رفــع‬\n     ‫احلكــم إلــى محكمــة االســتئناف بــدون الئحــة وقــرر املدعــي العــام‬\n     ‫االعتــراض بــدون الئحــة واالكتفــاء بــأوراق املعاملــة فأجيــب لطلبــه‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وقــد أقفلــت اجللســة الســاعة العاشــرة‬\n                                             ‫والنصــف وبــه حــرر يف ‪0000/0/00‬ه ـ‬\n     ‫ويف يــوم األربعــاء ‪0000/0/00‬ه ـ لــدي أنــا القاضــي باحملكمــة اجلزئيــة‬\n     ‫بالدمــام افتتحــت اجللســة الســاعة الثامنــة وقــد عــادت املعاملــة مــن‬\n     ‫محكمــة االســتئناف مرفقــا بهــا القــرار رقــم يف ‪0000/ 00 / 00‬ه ـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم مــن الدائــرة اجلزائيــة الثانيــة مبحكمة‬\n     ‫االســتئناف باملنطقــة الشــرقية لــذا جــرى إثباتــه وعليــه جــرى التوقيــع‬\n                                                              ‫حــرر يف ‪0000/0/00‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n     ‫املقيــدة لــدى احملكمــة برقــم ‪ ......‬وتاريــخ ‪0000/0/00‬ه ـ الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪ ......‬وتاريــخ‬\n     ‫‪0000/0/00‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ‪ ......‬املســجل برقــم ‪ ......‬وتاريــخ ‪0000/0/00‬ه ـ‬\n     ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد املدعــى عليــه يف قضيــة مخــدرات‬\n     ‫وســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n     ‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n     ‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                      ‫وســلم‪ .‬حــرر يف‪0000/0/0‬ه ـ ‪.‬‬\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":34,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"47f140bb9115e215979569e3b3217c15a0095598d1a33a50835ddb1a1b06f232","normalized_text_hash":"09c2663e907b4ca479675d591f2d9481103b9b2312e83e45e36efeaa446fd539","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p34-34188189"},{"id":"e060d495-83eb-576c-9c7b-7720da574b6d","document_type":"judgment","category":"judicial","subcategory":"general","title":"ا -رفع التكليف عن مسكر -شرب مسكر -املدعى عليه قاصر عق القاصر -رد الدعوى .","document_number":"3441105","case_number":"3377610","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام هكذا أجاب ثم جرى االطاع على الصك فوجدته طبق ما ذكر والد املدعى عليه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/19","year":"1434","subject":"ا -رفع التكليف عن مسكر -شرب مسكر -املدعى عليه قاصر عق القاصر -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك ‪ 3441105‬تاريخه‪1434/2/19 :‬هـ‬\n                   ‫رقم الدعوى‪3377610 :‬‬\n            ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34185998:‬تاريخه‪1434/04/13:‬هـ‬\n\n\n‫ا ‪ -‬رفــع التكليــف عــن‬\n                       ‫مســكر ‪ -‬شــرب مســكر ‪ -‬املدعــى عليــه قاصــر عقـ ً‬\n                                                        ‫القاصــر ‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( رفــع القلــم عــن ثالثــة عــن النائــم‬\n‫حتــى يســتيقظ وعــن الصغيــر حتــى يكبــر وعــن املجنــون حتــى يعقــل أو‬\n                               ‫يفيــق ) رواه النســائي وصححــه األلبانــي ‪.‬‬\n‫‪ -2‬قــال البهوتــي يف كشــاف القنــاع ‪ ( 14-8/7‬وألن غيــر املكلــف إذا‬\n‫ســقط عنــه التكليــف يف العبــادة واإلثــم يف املعاصــي فاحلــد املبنــي علــى‬\n                                                     ‫الــدرء بالشــبهة أولــى ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر ‪ ،‬وطلــب إثبــات‬\n‫مــا أســند إليــه واحلكــم عليــه بحــد املســكر ‪،‬حيــث ورد بــاغ عــن وجود‬\n‫املدعــى عليــه لــدى قيــادة الدوريات األمنية بحالة ســكر‪ ،‬وباستشــمامه‬\n‫اتضــح انبعــاث رائحــة املســكر مــن فمــه ‪،‬وأجــاب والــد املدعــى عليــه‬\n‫ا وهــو الولــي عليه‪،‬وأبــرز صــك الواليــة الصــادر مــن‬   ‫بــأن ابنــه قاصــر عقـ ً‬\n‫محكمــة الدمــام ‪ ،‬لــذا حكمــت احملكمــة بــرد الدعــوى بإقامــة حــد‬\n‫‪،‬وصــدق احلكــم‬‫املسكر‪،‬واعتـ ــرض ال ـمــدع ـ ــي الـ ـعـ ــام بــدون الئحــة ُ‬\n                                                    ‫مــن محكمــة االســتئناف ‪.‬‬\n                                                                                        ‫‪40‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا ‪ .....‬القاضــي باحملكمــة اجلزئيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n     ‫مــن هيئــة التحقيــق واالدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 33202681‬وتاريــخ ‪1433/1/30‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزئيــة بالدمــام برقــم ‪ 3377610‬وتاريــخ ‪1433/1/30‬ه ـ‬\n     ‫افتتحت اجللســة يف يوم األربعاء ‪1434/2/13‬هـ الســاعة العاشــرة والربع‬\n     ‫وفيهــا قــدم املدعــي العــام ‪ .....‬دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعيـ ًا عام ًا‬\n     ‫بدائــرة االدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪..... /‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬حيــث إنــه باالطــاع علــى‬\n     ‫محضــر تنفيــذ املهمــة املعــد مــن قبــل الدوريــات األمنيــة بالدمــام تبــن‬\n     ‫أنــه بتاريــخ ‪1432/12/11‬ه ـ انــه وأثنــاء قيــام أفــراد الدوريــات األمنيــة‬\n     ‫بعملهــم ورد بــاغ عــن وجــود شــخص لــدى قيــادة الدوريــات األمنيــة وأنــه‬\n     ‫بحالــة ســكر وباستشــمامه اتضــح انبعــاث رائحــة املســكر مــن فمــه‬\n     ‫وبســماع أقوالــه أقــر بشــربه املســكر يــوم القبــض عليــه وقــد انتهــى‬\n     ‫التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بشــرب املســكر وذلــك‬\n     ‫لألدلــة والقرائــن التاليــة‪ -1 :‬اعترافــه املــدون علــى الصفحــة (‪ )10‬مــن‬\n     ‫تقريــر األحــوال األمنيــة ‪ -2‬محضــر تنفيــذ املهمــة املنــوه عنــه املرفــق‬\n     ‫علــى اللفــة رقــم (‪ -3 )2‬محضــر االستشــمام املــدون علــى الصفحــة (‪)6‬‬\n     ‫مــن تقريــر األحــوال األمنيــة وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو‬\n     ‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرعا أطلــب‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليه بحد الســكر لقاء شــربه للمســكر‬\n\n‫‪41‬‬\n\f‫هكــذا ادعــى وبعــرض الدعــوى علــى والــد املدعــى عليــه احلاضــر ‪.....‬‬\n‫ا إن ابنــي‬ ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬أجــاب قائـ ً‬\n‫‪.....‬قاصــر عقلــي وأنــا الولــي عليــه وقــد صــدر بذلــك الصــك رقــم ‪.....‬يف‬\n‫‪ 1433/3/23‬الصــادر مــن احملكمــة العامــة بالدمــام هكــذا أجــاب ثــم‬\n‫جــرى االطــاع علــى الصــك فوجدتــه طبــق مــا ذكــر والــد املدعــى عليــه‬\n‫ـاء علــى مــا تقــدم مــن دعــوى‬‫وقــد جــرى إرفــاق صــورة منــه باملعاملــة فبنـ ً‬\n‫املدعــي العــام ومــا قدمــه والــد املدعــى عليــه مــن صــك الواليــة ونظــر ًا‬\n‫لقولــه صلــى اهلل عليــه وســلم (رفــع القلــم عــن ثالثــة عــن النائــم حتــى‬\n‫يســتيقظ وعــن الصغيــر حتــى يكبــر وعــن املجنــون حتــى يعقــل أو يفيــق)‬\n‫رواه النســائي وصححــه األلبانــي وقــال البهوتــي يف كشــاف القنــاع‬\n‫(‪ )8-7/14‬مــا نصــه‪( :‬وألن غيــر املكلــف إذا ســقط عنــه التكليــف‬\n‫يف العبــادة واإلثــم يف املعاصــي فاحلــد املبنــي علــى الــدرء بالشــبهة أولــى)‬\n‫لــذا كلــه فقــد قــررت رد دعــوى املدعــي العــام بإقامــة حــد املســكر‬\n‫علــى املدعــى عليــه لعــدم ثبوتــه وبذلــك حكمــت وبعــرض احلكــم علــى‬\n‫املدعــي العــام قــرر االعتــراض علــى احلكــم وطلــب االســتئناف مكتفيـ ًا‬\n‫بالئحــة الدعــوى العامــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                               ‫محمــد‪ .‬حــرر يف ‪1434/2/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يوم الثالثاء ‪1434/3/24‬هـ افتتحت اجللســة‬\n‫وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم ‪3457765‬‬\n‫يف ‪1434/3/8‬ه ـ املتضمــن (لوحــظ أن والــد املدعــى عليــه لــم يجــب على‬\n‫دعــوى املدعــي العــام باإليجــاب أو النفــي فعلــى فضيلتــه مالحظــة مــا‬\n‫ذكــر وإكمــال مــا يلــزم ومــن ثــم إعــادة املعاملــة واهلل املوفــق) عليــه‬\n\n\n                                                                                       ‫‪42‬‬\n\f     ‫أجيــب أصحــاب الفضيلــة بــأن والــد املدعــى عليــه هــو ولــي علــى القاصــر‬\n     ‫وال فائــدة مــن إجابتــه علــى الدعــوى باإليجــاب أو النفــي حيــث أن احلــد‬\n     ‫يســقط بســقوط التكليــف عــن املدعــى عليــه وأمــرت برفــع املعاملــة‬\n     ‫إلــى محكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                    ‫محمــد‪ .‬حــرر يف ‪1434/3/24‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n     ‫لــدى احملكمــة برقــم ‪/34/842718‬ج‪ 2‬وتاريــخ ‪1434/4/7‬ه ـ الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمة اجلزائيــة مبدينة الدمام برقم ‪34/688919‬‬\n     ‫وتاريــخ ‪1434/4/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشيخ‪...../‬املســجل برقــم ‪ 3441105‬وتاريخ ‪1434/2/19‬هـ‬\n     ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ...../‬يف قضيــة ســكر وقــد تضمــن‬\n     ‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n     ‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n     ‫علــى قرارنــا رقــم ‪/3457765‬ج‪/2‬ب وتاريــخ ‪1434/3/8‬ه ـ قررنــا‬\n     ‫املصادقــة علــى احلكــم بعــد اجلــواب األخيــر‪ .‬واهلل املوفــق وصلــى اهلل‬\n             ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/4/10‬ه ـ ‪.‬‬\n\n\n\n\n‫‪43‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":40,"source_page_end":43,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"191494a2da48f0e19dab84fb2d3d73d14314f55bad5ebb7c34a187a55c18ac56","normalized_text_hash":"3e81714abefdb26d5bc58eb56813bd8e4f062548247bba824c7f12fe74b9c82f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p40-3441105"},{"id":"300034b9-0bac-595a-baa1-221271ad2f4b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -حيازة بقصد االستعمال -قيادة سيارة حتت تأثير املسكر -قبول الرجوع عن اإلقرار يف احلدود -التعزير باجللد -رد الدعوى بإقامة احلد .","document_number":"34190599","case_number":"3422842","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/17","year":"1434","subject":"مسكر -شرب مسكر -حيازة بقصد االستعمال -قيادة سيارة حتت تأثير املسكر -قبول الرجوع عن اإلقرار يف احلدود -التعزير باجللد -رد الدعوى بإقامة احلد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 34190599:‬تاريخه‪1434/4/17:‬هـ‬\n                     ‫رقم الدعوى‪3422842:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34217401:‬تاريخه‪1434/05/20:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب مســكر ‪ -‬حيــازة بقصــد االســتعمال ‪ -‬قيــادة ســيارة حتــت‬\n‫تأثيــر املســكر ‪ -‬قبــول الرجــوع عــن اإلقــرار يف احلــدود ‪ -‬التعزيــر باجللد‬\n                                               ‫‪ -‬رد الدعــوى بإقامــة احلــد ‪.‬‬\n\n\n\n\n‫رجــوع املقــر عــن إقــراره مقبــول عنــد عامــة الفقهــاء قــال صاحــب الشــرح‬\n‫( ومتــى رجــع املقــر باحلــد عــن إقــراره قبــل منــه وإن رجــع يف أثنــاء احلــد‬\n‫لــم يتمــم وجملــة ذلــك أن شــرط إقامــة احلــد باإلقــرار البقــاء عليــه‬\n    ‫إلــى متــام احلــد فــإن رجــع عــن إقــراره كــف عنــه ) قــال يف اإلنصــاف‬\n                           ‫( هذا املذهب يف جميع احلدود )‪. 207-206/26‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليه بحيازة املسـ ـكـ ــر وشــربه وقيادة‬\n‫الســيارة حتــت تأثيــر املســكر ‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم‬\n‫بحــد املســكر وتعزيــره لقــاء احليــازة وإفهامــه بــأن القيــادة حتــت تأثيــر‬\n‫املســكر عقوبتهــا عائــدة للجهــة املختصــة ‪،‬حيــث مت االشــتباه بالســيارة‬\n‫التــي يقودهــا املدعــى عليــه فتــم اســتيقافه مــن قبــل الدوريــة األمنيــة ومت‬\n‫ضبــط علبــة يشــتبه أن بداخلهــا شــراب مســكر حيــث قــام املدعــى‬\n‫عليــه برميهــا وباستشــمام املدعــى عليــه انبعــث رائحــة املسـ ـك ـ ــر مــن‬\n\n                                                                                       ‫‪44‬‬\n\f     ‫أن ـفــاسـ ــه ‪،‬وأثبــت التقريــر الكيميائــي إيجابيــة العينــة ملــادة الكحــول‬\n     ‫‪ ،‬وأقــر املدعــى عليــه باحليــازة وأنكــر شــرب املســكر وقيــادة الســيارة‬\n     ‫حتــت تأثيــره ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بجلــده‬\n     ‫ثالثــن جلــدة ورد طلــب املدعــي العــام احلكــم علــى املدعــى عليــه بحــد‬\n     ‫املســكر وجلــد املدعــى عليــه ســبعني جلــدة للتهمــة القويــة بشــرب‬\n     ‫املســكر وقنــع املدعــى عليــه ‪،‬واعتــرض املدعــي العــام بــدون الئحــة ‪،‬‬\n                                     ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬    ‫ُ‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمة العامة بعرعر‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n     ‫بعرعــر برقــم ‪ 3422842‬وتاريــخ ‪ 1434/01/13‬ه ـ املقيــدة باحملكمــة‬\n     ‫برقــم ‪ 34109255‬وتاريــخ ‪ 1434/01/13‬ه ـ ففــي يــوم الثالثــاء‬\n     ‫املوافق‪1434/04/16‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا قــدم‬\n     ‫املدعــي العــام ‪.....‬الئحــة دعــواه ‪.....‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n     ‫ا ‪ :‬إنــه بتاريــخ ‪1433/12/19‬ه ـ و أثنــاء قيــام دوريــة االمــن‬            ‫‪.....‬قائ ـ ً‬\n     ‫بعملهــا املعتــاد ويف متــام الســاعة الرابعــة والنصــف مــن صبــاح يــوم االحــد‬\n     ‫مت االشــتباه بســيارة مــن نــوع حتمــل اللوحــة رقــم (‪ ).....‬وباســتيقافها يف‬\n     ‫شــارع ‪.....‬مت ضبــط علبــة ســعة نصــف لتــر يشــتبه أن بداخلهــا شــراب‬\n     ‫مســكر (مملــوء ثالثــة اربــاع العلبــة ) قــام برميهــا قائــد الســيارة ويشــتبه‬\n     ‫ان يكــون بحالــة غيــر طبيعيــة ‪،‬فتــم القبــض علــى املتهــم واحالتــه جلهــة‬\n     ‫االختصــاص وباسشــمامه اتضــح انبعــاث رائحــة كريهــة مــن انفاســه‬\n     ‫تشــبه رائحــة املســكر و باســتجواب املتهــم أقــر بشــرب املســكر وقيــادة‬\n‫‪45‬‬\n\f‫الســيارة حتــت تأثيــره وقــد اثبــت التقريــر الكيميائــي الشــرعي الصــادر‬\n‫مــن جلنــة حتــري الكحــول مبستشــفى عرعــر املركــزي رقم(بــدون)‬\n‫وتاريــخ ‪1434 /1/3‬ه ـ إيجابيــة عينــة دم املتهــم ملــادة الكحــول‪ .‬كمــا‬\n‫أثبــت تقريــر الســموم الصــادر مــن إدارة األدلــة اجلنائيــة برقــم( ‪/.....‬‬\n‫ســموم لعــام ‪1433‬هــ) ايجابيــة العينــة املرســلة للفحــص ملــادة الكحــول‬\n‫وقــد انتهــى التحقيــق إلــى اتهــام ‪ ..... /‬بشــرب املســكر وحيازتــه بقصــد‬\n‫االســتعمال وقيــادة املركبــة حتــت تأثيــر املســكر وحيــث أن مــا أقــدم‬\n‫عليــه املذكــور و هــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم و‬\n‫معاقــب عليــه شــرعا ‪ ،‬لــذا أطلــب اثبــات إدانتــه مبــا أســند اليــه واحلكــم‬\n‫عليــه بحــد املســكر ‪ ،‬وبعقوبــة تعزيريــة لقــاء حيازتــه للمســكر ‪،‬‬\n‫واثبــات ادانتــه بقيــادة الســيارة حتــت تأثيــر املســكر وافهامــه بــان عقابــه‬\n‫عائــد للجهــة املختصــة وفقــا للمــادة (‪ )1/1/74‬مــن نظــام املــرور والئحتــه‬\n‫التنفيذيــة هكــذا ادعــى ‪ ،‬وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى‬\n‫ا ‪ :‬كل مــا جــاء يف دعــوى املدعــي العــام مــن‬   ‫املدعــي العــام أجــاب قائ ـ ً‬\n‫شــربي للمســكر وقيادتــي للســيارة حتــت تأثيــره فهــذا غيــر صحيــح ‪،‬‬\n‫وأمــا مــا جــاء يف دعــواه مــن أنــي حــزت املســكر لقصــد االســتعمال فهذا‬\n‫صحيــح هكــذا أجــاب ‪ ،‬ثــم ســألت املدعــي العــام عــن بينتــه فأجــاب‬\n‫ا ‪ :‬ليــس لــدي ســوى مــا يف أوراق املعاملــة ‪ ،‬فجــرى االطــاع علــى‬       ‫قائ ـ ً‬\n‫أوراق املعاملــة وعلــى محضــر االســتجواب لفــه (‪ 10‬ـ ‪ ) 11‬واملتضمــن‬\n‫إقــرار املدعــى عليــه حتقيق ـ ًا بشــربه للمســكر وقيــادة الســيارة حتــت‬\n‫ا ‪ :‬صحيــح‬    ‫تأثيــره ‪ ،‬وســألت املدعــى عليــه عــن ذلــك فأجــاب قائ ـ ً‬\n‫أنــي أقــررت بذلــك ولكــن إمنــا فعلــت ذلــك ألخــرج مــن الســجن ولــم‬\n‫يكرهنــي أحــد علــى هــذا اإلقــرار هكــذا قــرر ‪ ،‬كمــا جــرى االطــاع‬\n\n\n                                                                                       ‫‪46‬‬\n\f     ‫علــى تقريــر فحــص عينــة دم املدعــى عليــه لفــه (‪ )18‬واملتضمــن إيجابيــة‬\n     ‫ا‪:‬‬ ‫العينــة ملــادة الكحــول وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫هــذا غيــر صحيــح ‪ ،‬كمــا جــرى االطــاع علــى محضــر اإلستشــمام لفــه‬\n     ‫(‪ )1‬صفحــة (‪ )11‬واملتضمــن (أنــه جــرى استشــمام املدعــو‪..... /‬واتضــح‬\n     ‫انبعــاث رائحــة كريهــة مــن أنفاســه يشــتبه أنهــا رائحــة مســكر‪،‬‬\n     ‫ا ‪ :‬ال صحــة ملــا جــاء يف‬  ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫هــذه الشــهادة هكــذا قــرر ‪ ،‬وقــد جــرى االطــاع علــى تقريــر الســموم‬\n     ‫لفــه (‪ )15‬واملتضمــن إيجابيــة عينــة القــارورة املأخــوذة مــن ســيارة املدعــى‬\n     ‫عليــه ملــادة الكحــول ‪ ،‬ثــم ســألت املدعــى عليــه عــن ســوابقه فأجــاب‬\n     ‫ا ‪ :‬ال ســوابق علــي وهلل احلمــد ‪ ،‬فبنــاء ًا علــى مــا تقــدم مــن الدعــوى‬ ‫قائـ ً‬\n     ‫واإلجابــة ‪ ،‬وإلقــرار املدعــى عليــه بحيــازة املســكر لقصــد االســتعمال‬\n     ‫‪ ،‬وإلنــكاره شــرب املســكر وقيــادة الســيارة حتــت تأثيــره وملــا جــاء يف‬\n     ‫إقــرار املدعــى عليــه املــدون حتقيقـ ًا ومحضــر اإلستشــمام وتقرير فحص‬\n     ‫عينــة الــدم وتقريــر الســموم املذكــورة أعــاه ‪ ،‬ولرجوعــه عــن اإلقــرار‬\n     ‫املذكــور والرجــوع عــن اإلقــرار يف احلــدود مقبــول عنــد عامــة الفقهــاء‬\n     ‫قــال صاحــب الشــرح ( ومتــى رجــع املقــر باحلــد عــن إقــراره قبــل منــه وإن‬\n     ‫رجــع يف أثنــاء احلــد لــم يتمــم وجملــة ذلــك أن شــرط إقامــة احلــد باإلقــرار‬\n     ‫البقــاء عليــه إلــى متــام احلــد فــإن رجــع عــن إقــراره كــف عنــه ) قــال‬\n     ‫صاحــب اإلنصــاف ( هــذا املذهــب يف جميــع احلــدود ) ‪2080207/26‬‬\n     ‫‪ ،‬ولكــون شــهادة الشــهود املدونــة بعاليــه ليــس فيهــا اجلــزم بانبعــاث‬\n     ‫رائحــة املســكر ‪ ،‬ولكــون إقامــة حــد املســكر بنــاء ًا علــى الرائحــة‬\n     ‫عنــد اجلــزم بهــا مختلــف فيــه عنــد أهــل العلــم فعنــد عــدم اجلــزم مــن بــاب‬\n     ‫أولــى ‪ ،‬وألن احلــدود تــدرأ بالشــبهات ‪ ،‬ولعــدم وجــود ســوابق جنائيــة‬\n\n\n‫‪47‬‬\n\f‫علــى املدعــى عليــه ‪ ،‬وجلميــع مــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى‬\n‫عليــه ‪.....‬بحيــازة املســكر بقصــد االســتعمال ‪ ،‬ولــم يثبــت لــدي إدانتــه‬\n‫بشــرب املســكر وقيــادة الســيارة حتــت تأثيــره ‪ ،‬وعليــه فقــد قــررت رد‬\n‫طلــب املدعــي العــام احلكــم علــى املدعــى عليــه بحــد املســكر وإثبــات‬\n‫إدانتــه بقيــادة الســيارة حتــت تأثيــره ‪ ،‬ولكــن لتوجــه التهمــة القويــة عليه‬\n‫فقــد قــررت مــا يلــي ‪ :‬أو ًال ‪ /‬جلــد املدعــى عليــه ســبعون جلــدة لقــاء التهمة‬\n‫القويــة بشــرب املســكر ‪ ،‬ثانيـ ًا ‪ /‬جلــد املدعــى عليــه ثالثــون جلــدة لقــاء‬\n‫حيــازة املســكر وبذلــك حكمــت وبعرضــه عليهمــا قــرر املدعــى عليــه‬\n‫القناعــة باحلكــم وقــرر املدعــي العــام املعارضــة بــدون الئحــة وعليــه فقــد‬\n‫قــررت رفــع املعاملــة إلــى محكمــة االســتئناف مبنطقــة اجلــوف كاملتبــع‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/16‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الثانيــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف باجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر الشــيخ‪...../‬‬\n‫برقــم ‪34913002‬وتاريخ‪1434/4/28‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة الشــيخ ‪...../‬برقــم‪ 34190599‬وتاريخ‪1434/4/17‬ه ـ اخلــاص‬\n‫بدعــوى املدعــي العــام ضــد ‪..... /‬التهامــه بشــرب املســكر وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون و مفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــرر باألكثريــة املصادقــة علــى احلكم‬\n ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                        ‫‪48‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":44,"source_page_end":48,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fe8a58b9e90a4e8eb7deb33f06840f58b9742fb86ba8f9c77fe50b089795a633","normalized_text_hash":"bddae54e98194db4882a9294a0cd849efbfefa16c583523b35a54e3c908b84ba","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p44-34190599"},{"id":"53b0f911-6b98-5fe6-953b-4b54897b6f1f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة بقصد االستعمال -قيادة سيارة حتت تأثير املسكر -املدعى عليه أجنبي غير مسلم -ال يحد بحد املسكر غير املسلم -تعزير باجللد .","document_number":"3439861","case_number":"3466341","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/18","year":"1434","subject":"مسكر -شرب املسكر -حيازة بقصد االستعمال -قيادة سيارة حتت تأثير املسكر -املدعى عليه أجنبي غير مسلم -ال يحد بحد املسكر غير املسلم -تعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3439861 :‬تاريخه‪1434/2/18:‬هـ‬\n                        ‫رقم الدعوى‪3466341:‬‬\n                ‫رقم قرار التصديق من محكمة‬\n     ‫االستئناف‪ 3451337:‬تاريخه‪1434/03/01:‬هـ‬\n\n\n     ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة بقصــد االســتعمال ‪ -‬قيــادة ســيارة حتــت‬\n     ‫تأثيــر املســكر ‪ -‬املدعــى عليــه أجنبــي غيــر مســلم ‪ -‬ال يحــد بحــد املســكر‬\n                                                  ‫غيــر املســلم ‪ -‬تعزيــر باجللــد ‪.‬‬\n\n\n\n\n     ‫قال البهوتي رحمه اهلل ( وال يحد ذمي وال مســتأمن بشــربه أي املســكر‬\n                                      ‫ولــو رضــي بحكمنــا ألنــه يعتقــد حله ) ‪.‬‬\n\n\n\n\n     ‫ادعى املدعي العام ضد املدعى عليه وافد غير مســلم بشــرب املســكر‬\n     ‫وحيازتــه بقصــد االســتعمال وقيــادة الســيارة حتــت تأثيــر املســكر‬\n     ‫والتســبب يف حــادث مــروري وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة لقــاء شــرب املســكر وحيازتــه وإثبــات إدانتــه بالقيــادة‬\n     ‫حتــت تأثيــره وإفهامــه بــأن العقوبــة عائــدة لولــي األمــر ‪،‬حيــث قبــض‬\n     ‫علــى املدعــى عليــه مــن قبــل دوريــة أمــن الطــرق بعــد ورود بــاغ بوقــوع‬\n     ‫حــادث مــروري تســبب فيــه املدعــى عليــه كمــا تبــن بأنــه بحالــة غيــر‬\n     ‫طبيعيــة و باستشــمامه انبعثــت رائحــة املســكر منــه وبتفتيــش الســيارة‬\n     ‫عثــر بداخلهــا علــى قــارورة فيهــا ســائل تنبعــث منهــا رائحــة املسكـ ــر ‪،‬‬\n     ‫صــادق املدعــى عليــه علــى الدعــوى بواســطة املترجــم ‪،‬وبنــاء علــى مــا‬\n‫‪49‬‬\n\f‫تقــدم حكمــت احملكمــة بتعزيــره بجلــده خمســن جلــده دون احلــد ألن‬\n‫حــد املســكر ال يقــام علــى غيــر املســلم وبســجنه ملــدة شــهرين وإدانــة‬\n‫املدعــى عليــه بقيــادة الســيارة حتــت تأثيــر املســكر وإفهامه بــأن عقوبته‬\n‫عائــدة لولــي األمــر وإبعــاده عــن اململكــة بعــد انتهــاء محكوميتــه وقنــع‬\n‫وصــدق احلكــم مــن‬ ‫املدعــى عليــه واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                      ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬‫أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ‪ 1982‬وتاريــخ ‪1434/02/10‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‬\n‫‪ 34333533‬وتاريــخ ‪1434/02/10‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n‫الرئيــس برقــم ‪ 3466341‬وتاريــخ ‪1434/02/10‬ه ـ فتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام ‪ ..... /‬امل َُع ّمــد بالترافــع أمــام احملكمــة‬\n‫طرفنــا مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام‬\n‫مبحافظــة األحســاء ذي الرقــم ‪.....‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر‬\n‫عامــا بدائــرة االدعــاء العــام مبحافظــة‬  ‫ا بصفتــي مدعي ـ ًا ً‬   ‫دعــواه قائ ـ ً‬\n‫األحســاء أدعــي علــى ‪ 43 ،..... :‬عام ـ ًا ‪ ،‬غيــر مســلم ‪ ،‬املهنــة ســائق‬\n‫ســيارة عمومــي « هنــدي اجلنســية « مبوجــب رخصــة اإلقامــة رقــم ( ‪).....‬‬\n‫أوقــف بتاريــخ ‪1434/1/15‬ه ـ وأحيــل لشــعبة ســجن محافظــة األحســاء‬\n‫ا لديهــم برقــم ( ‪ ).....‬اســتناد ًا للمــادة ( ‪ ) 108‬مــن نظــام‬ ‫وســجل نزي ـ ً‬\n‫اإلجــراءات اجلزائيــة لعــدم وجــود كفيــل يكفلــه ‪ ،‬أو مقــر ســكن‬\n\n                                                                                       ‫‪50‬‬\n\f     ‫ثابــت لــه ‪ .‬حيــث إنــه بتاريــخ ‪1434/1/15‬ه ـ مت القبــض علــى املدعــى‬\n     ‫عليــه مــن قبــل رجــال دوريــات أمــن الطــرق إثــر ورود بــاغ مفــاده وقــوع‬\n     ‫حــادث مــروري علــى طريــق الريــاض تســبب فيــه املدعــى عليــه أثنــاء‬\n     ‫قيادتــه شــاحنة مــن نــوع مرســيدس رأس صنــع ( ‪ 2003‬م ) زرقــاء اللــون‬\n     ‫حتمــل اللوحــة رقــم ‪ ).....‬وذلــك باصطدامــه بشــاحنة مــن نــوع فولفــو مــن‬\n     ‫اخللــف ( مت معاجلتهــا مــن قبــل جهــة االختصــاص ) ‪ ،‬ومبعاينــة املدعــى‬\n     ‫عليــه اتضــح بأنــه يف حالــة غيــر طبيعيــة ( ســكر ) ‪ ،‬وبتفتيــش الشــاحنة‬\n     ‫عثــر بداخلهــا علــى قــارورة مــاء صحــة ســعة لتــر بهــا الربــع مــن ســائل‬\n     ‫شــفاف عــدمي اللــون تنبعــث منهــا رائحــة املســكر ‪ ،‬وباستشــمامه اتضــح‬\n     ‫انبعــاث رائحــة املســكر مــن جوفــه ‪ .‬وباســتجواب املدعــى عليــه أقــر‬\n     ‫بواقعــة القبــض عليــه وشــربه للمســكر وحيازتــه لقــارورة مــاء صحــة‬\n     ‫صغيــرة بهــا الربــع مــن اخلمــر املصنــع محلي ـ ًا بعــد أن قــام بشــرائه مــن‬\n     ‫شــخص نيبالــي مببلــغ ( ‪ ) 50‬خمســون ريــا ًال ‪ ،‬وقيادتــه للســيارة حتــت‬\n     ‫تأثيــره ‪ ،‬والتســبب يف حــادث مــروري ‪ .‬وقــد أســفر التحقيــق عــن توجيــه‬\n     ‫االتهــام لــه بشــرب املســكر وحيازتــه لــه ( املوصوفــة يف الدعوى ) بقصد‬\n     ‫الشــرب ‪ ،‬وقيــادة الســيارة حتــت تأثيــره ؛ وذلــك لألدلــة والقرائــن التاليــة‬\n     ‫‪ .1 :‬إقــراره املــدون علــى الصفحــة رقــم ( ‪ ) 6‬مــن دفتــر التحقيــق لفــة رقــم‬\n     ‫( ‪ .2 . ) 1‬محضــر االستشــمام املــدون علــى الصفحــة رقــم ( ‪ ) 10‬مــن‬\n     ‫دفتــر التحقيــق لفــة رقــم ( ‪ .3 . ) 1‬محضــر القبــض املرفــق علــى لفــة رقــم‬\n     ‫( ‪ .4 . ) 18‬محضــر التفتيــش املــدون علــى الصفحــة رقــم ( ‪ ) 7‬مــن دفتــر‬\n     ‫التحقيــق لفــة رقــم ( ‪ . ) 1‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر‬\n     ‫لــه علــى ســوابق جنائيــة مســجلة ‪ .‬وحيــث إن مــا أق ــدم عليــه املدعــى علي ــه‬\n     ‫املذكـور وهـو بكامل أهليته املعتبرة شـرع ًا فعل محـرم ومعـاقب عليـه‬\n\n\n‫‪51‬‬\n\f‫ش ــرع ًا ونظام ـ ًا ‪ ،‬أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه باآلتــي ‪:‬‬\n‫‪ .1‬بعقوبــة تعزيريــة لقــاء شــربه للمســكر وحيازتــه لــه ( املوصوفــة يف‬\n‫الدعــوى ) بقصــد الشــرب ‪ ،‬وتشــديد العقوبــة عليــه لقــاء اســتهتاره‬\n‫بــأرواح اآلخريــن لقيادتــه الســيارة حتــت تأثيــر مــا تعاطــاه وارتكابــه‬\n‫ا ببرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة‬        ‫حلــادث مــروري عم ـ ً‬\n‫رقــم ( ‪ ) 65358‬وتاريــخ ‪1431/6/15‬ه ـ ‪ .2.‬إثبــات قيادتــه للســيارة وهــو‬\n‫حتــت تأثيــر شــرب املســكر ‪ ،‬وإفهامــه بــأن عقابــه علــى ذلــك عائــد‬\n‫للجهــة املختصــة اســتنا ًدا للفقــرة ( أو ًال ) مــن املــادة ( ‪ ) 68‬مــن نظــام‬\n‫املــرور هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد‬\n‫مــن هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه بواســطة املترجــم‪.....‬‬\n‫هنــدي اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة مــن جــوازات الهفــوف‬\n‫ا ‪ :‬مــا‬‫ـروف لدينــا بالعدالــة فأجــاب قائ ـ ً‬\n                                           ‫برقــم (‪ ).....‬مســلم الديانــة معـ ٌ‬\n‫ذكــره املدعــي العــام مــن اتهامــي بشــرب املســكر وحيازتــي لقــارورة‬\n‫مــاء صحــة صغيــرة بهــا الربــع مــن اخلمــر املصنــع محليـ ًا بقصــد الشــرب‬\n‫وقيادتــي للســيارة حتــت تأثيــر املســكر وتســببي يف حــادث مــروري‬\n‫كل ذلــك صحيــح وأنــا غيــر مســلم هكــذا أجــاب ثــم جــرى االطــاع‬\n‫علــى جميــع أوراق املعاملــة ومنهــا كــرت ســوابق املدعــى عليــه املتضمــن‬\n‫عــدم وجــود ســوابق عليــه كمــا جــرى االطــاع علــى مذكــرة إيقــاف‬\n‫ـاء علــى‬‫املدعــى عليــه املتضمنــة أنــه أوقــف بتاريــخ ‪1434/01/15‬ه ـ فبنـ ً‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليهــم‬\n‫أن‬\n ‫والتأكــد مــن أهليتهــم وبعــد دراســة أوراق املعاملــة وتأملهــا ومبــا َّ‬\n‫املدعــى عليهــم أقـ ّـر بدعــوى املدعــي العــام مــن اتهامــه بشــرب املســكر‬\n‫أن حــد املســكر ال‬   ‫ودفــع بأ َّنــه غيــر مســلم وملــا قــرره أهــل العلــم مــن َّ‬\n\n                                                                                          ‫‪52‬‬\n\f     ‫يقــام علــى غيــر املســلم قــال البهوتــي ‪ -‬رحمــه اهلل تعالــى ‪ « : -‬وال يحـ ّـد‬\n     ‫ذمـ ٌّـي وال مســتأمن بشــربه أي املســكر ولــو رضــي بحكمنــا ألنــه يعتقــد‬\n     ‫حلــه « ومبــا أ َّنــه أقـ َّـر بشــرب اخلمــر يف اململكــة وهــذا مــن احملـ َّـرم شــرع ًا‬\n     ‫ونظام ـ ًا ؛ إذ قــد التــزم بالتعليمــات التــي متنــع شــرب اخلمــر يف اململكــة‬\n     ‫حلظــة دخولــه لهــا ممــا يســتوجب تعزيــره باجللــد دون حـ ِّـد املســكر‬\n     ‫ومبــا أ َّنــه أقـ َّـر بحيــازة قــارورة مــاء صحــة صغيــرة بهــا الربــع مــن اخلمــر‬\n     ‫املصنــع محلي ـ ًا بقصــد الشــرب وتســببه يف وقــوع حــادث مــروري ومبــا‬\n     ‫أن مــا صــدر منــه مــن احملــرم شــرع ًا يســتوجب تعزيــره ومبــا أ َّنــه أقـ َّـر‬       ‫َّ‬\n     ‫بقيــادة الســيارة حتــت تأثيــر املســكر وإثبــات إدانتــه بذلــك لــدى هــذه‬\n     ‫احملكمــة والعقوبــة عنــد ولــي األمــر حســب األنظمــة املرعيــة التــي ال‬\n     ‫تتعــارض مــع املصالــح الشــرعية لــذا كلــه وألجــل احلــق العــام حكمــت‬\n     ‫ـدي إدانــة املدعــى عليــه بشــرب‬  ‫علــى املدعــى عليــه مبــا يلــي‪ :‬أوالً‪ /‬ثبــت لـ َّ‬\n     ‫اخلمــر وعزرتــه لقــاء ذلــك بجلــده خمســون جلــدة دفعــة واحــدة ثاني ـ ًا ‪/‬‬\n     ‫ـدي إدانــة املدعــى عليــه بحيــازة قــارورة مــاء صحــة صغيــرة بهــا‬           ‫ثبــت لـ َّ‬\n     ‫الربــع مــن اخلمــر املصنــع محليـ ًا بقصــد الشــرب وتســببه يف وقــوع حــادث‬\n     ‫مــروري وعزرتــه لقــاء ذلــك بســجنه ملــدة شــهرين مــن تاريــخ إيقافــه علــى‬\n     ‫ـدي إدانتــه بقيــادة الســيارة حتــت تأثيــر‬     ‫ذمــة القضيــة ثالث ـ ًا ‪ /‬ثبــت لـ َّ‬\n     ‫ـأن عقوبتــه عائــدة لولــي األمــر ‪ .‬رابع ـ ًا ‪ /‬يؤخــذ‬    ‫املســكر وأفهمتــه بـ َّ‬\n     ‫عليــه التعهــد بعــدم العــودة ملثــل مــا صــدر منــه ويبعــد عــن اململكــة اتقــاء‬\n     ‫شــره بعــد انتهــاء محكوميتــه واســتيفاء مالــه ومــا عليــه مــن حقــوق ‪.‬‬\n     ‫وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه يف متييــز‬\n     ‫احلكــم بواســطة املترجــم قــرر قناعتــه بــه وطلــب املدعــي العــام رفــع‬\n     ‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون الئحــة‬\n\n\n‫‪53‬‬\n\f‫اعتراضيــة مكتفيـ ًا مبــا ورد يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة‬\n‫الثانيــة عشــرة والنصــف وصلــى اهلل وسـلَّم علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه أجمعــن حــرر يف ‪1434/02/17‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/450701‬ج‪ 2‬وتاريــخ ‪1434/2/23‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫برقــم ‪ 34/333533‬وتاريــخ ‪1434/2/19‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشيخ‪...../‬املســجل برقــم ‪3439861‬‬\n‫وتاريــخ ‪1434/2/18‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‪(...../‬هنــدي‬\n‫اجلنســية) يف قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n            ‫نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/30‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪54‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":49,"source_page_end":54,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5aa7bcdf744d82c8c115ab68b202cf7ebe4026497d1c592fed40dc2118db0bc9","normalized_text_hash":"152fb5eb291d271c99d5e49f56d3505513e6172bc71a030b742c036c75a5abee","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p49-3439861"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
